export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let stepCount = 0;
  let uLag = 0;
  let kT = 20.5;
  let massEst = 0.775;

  // Observer states
  let vxEst = 0, vyEst = 0, vzEst = 0;
  let dxEst = 0, dyEst = 0, dzEst = 0;

  // Attitude trim integral (compensates weak motor steady-state attitude offset)
  let rollTrim = 0, pitchTrim = 0;
  let lastRollDes = 0, lastPitchDes = 0, lastThrust = 0.5;

  // Navigation state
  let targetIndex = -1;
  let phase = 'approach';
  let alignCount = 0;
  let descendStarted = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (stepCount === 0) {
        vxEst = v.x; vyEst = v.y; vzEst = v.z;
      } else {
        // Update motor lag model (tau ~ 0.04s)
        uLag += (lastThrust - uLag) * (1 - Math.exp(-dt / 0.04));

        const airborne = p.y > 0.095;
        const dragCoeff = 0.42 / massEst;

        if (airborne) {
          const ayModel = kT * uLag * dirY - dragCoeff * vyEst - 9.81;
          const vyPred = vyEst + (ayModel + dyEst) * dt;
          const evy = v.y - vyPred;
          vyEst = vyPred + 0.65 * evy;
          dyEst = clamp(dyEst + 18.0 * evy, -8.0, 8.0);

          // Adapt kT slowly from dyEst
          if (uLag > 0.25 && dirY > 0.7) {
            kT = clamp(kT + 0.8 * dyEst * dt, 13.0, 27.0);
            massEst = clamp(15.0 / kT, 0.6, 0.95);
          }
        } else {
          vyEst = v.y;
          dyEst = 0;
        }

        // Specific thrust estimate from vertical balance + motor model
        const uSpec = clamp(kT * uLag + (dirY > 0.5 ? dyEst / dirY : 0), 0, 28.0);
        const axModel = uSpec * dirX - dragCoeff * vxEst;
        const azModel = uSpec * dirZ - dragCoeff * vzEst;

        if (airborne) {
          const vxPred = vxEst + (axModel + dxEst) * dt;
          const evx = v.x - vxPred;
          vxEst = vxPred + 0.68 * evx;
          dxEst = clamp(dxEst + 20.0 * evx, -10.0, 10.0);

          const vzPred = vzEst + (azModel + dzEst) * dt;
          const evz = v.z - vzPred;
          vzEst = vzPred + 0.68 * evz;
          dzEst = clamp(dzEst + 20.0 * evz, -10.0, 10.0);

          // Attitude trim update: compare desired attitude from previous step with actual
          rollTrim = clamp(rollTrim + 1.8 * (lastRollDes - att.roll) * dt, -0.28, 0.28);
          pitchTrim = clamp(pitchTrim + 1.8 * (lastPitchDes - att.pitch) * dt, -0.28, 0.28);
        } else {
          vxEst = v.x;
          vzEst = v.z;
        }
      }
      stepCount++;

      // Navigation & Waypoint Logic
      let tx, ty, tz;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 6.0, kdX = 4.2;
      let kpZ = 7.5, kdZ = 4.8;
      let kpY = 7.5, kdY = 4.5;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'approach';
          alignCount = 0;
        }

        // Keep y and z targeted straight at the gate centre (with brief safety blend right after crossing previous gate)
        ty = gate.y;
        tz = gate.z;

        const errZ = Math.abs(p.z - gate.z);
        const errY = Math.abs(p.y - gate.y);
        const distToPlane = gate.x - p.x;
        const tCross = clamp(distToPlane / Math.max(vxEst, 0.35), 0, 0.35);
        const predZ = Math.abs(p.z + vxEst > 0 ? (p.z + vzEst * tCross - gate.z) : (p.z - gate.z));
        const predY = Math.abs(p.y + vzEst * 0 + vyEst * tCross - gate.y);

        const safeNow = errZ < 0.020 && predZ < 0.022 && Math.abs(vzEst) < 0.16 && errY < 0.085 && predY < 0.095 && Math.abs(vyEst) < 0.35;
        const stillSafe = errZ < 0.025 && predZ < 0.026 && Math.abs(vzEst) < 0.22 && errY < 0.105 && predY < 0.115;

        if (phase === 'approach') {
          tx = gate.x - 0.26;
          if (distToPlane < 0.38 && safeNow) {
            alignCount++;
            if (alignCount >= 3) phase = 'cross';
          } else {
            alignCount = 0;
          }
        }

        if (phase === 'cross') {
          // If a sudden gust knocks us out of alignment BEFORE we cross gate.x, abort and re-align!
          if (distToPlane > 0.02 && !stillSafe) {
            phase = 'approach';
            alignCount = 0;
            tx = gate.x - 0.24;
            kpX = 8.5; kdX = 5.0;
          } else {
            tx = gate.x + 0.32;
            vxRef = 0.65;
          }
        }

        // High precision on Z and Y near gate plane
        if (distToPlane < 0.55) {
          kpZ = 10.5; kdZ = 5.8;
          kpY = 9.0; kdY = 5.2;
        }
      } else {
        // After all 3 gates: fly to landing pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const horizErr = Math.hypot(p.x - pad.x, p.z - pad.z);
        const horizSpeed = Math.hypot(vxEst, vzEst);

        if (!descendStarted) {
          // Smooth altitude ramp down as we approach the pad
          ty = clamp(0.18 + 0.85 * horizErr, 0.18, 1.05);
          if (horizErr < 0.11 && horizSpeed < 0.25 && p.y < 0.28) {
            descendStarted = true;
          }
        }
        if (descendStarted) {
          if (horizErr > 0.135) {
            // Hold just above floor if gust pushes us near pad edge
            ty = 0.12;
          } else {
            ty = 0.05;
          }
          kpX = 7.5; kdX = 4.8;
          kpZ = 7.5; kdZ = 4.8;
        }
      }

      const dragCoeff = 0.42 / massEst;

      // Desired accelerations including disturbance rejection and drag compensation
      const axDes = kpX * (tx - p.x) + kdX * (vxRef - vxEst) - dxEst + dragCoeff * vxEst;
      const azDes = kpZ * (tz - p.z) + kdZ * (vzRef - vzEst) - dzEst + dragCoeff * vzEst;
      const ayDes = kpY * (ty - p.y) + kdY * (vyRef - vyEst) + dragCoeff * vyEst;

      const maxTiltAcc = (obs.gateIndex === 3 && p.y < 0.13) ? 1.5 : 6.8;
      const Tx = clamp(axDes, -maxTiltAcc, maxTiltAcc);
      const Tz = clamp(azDes, -maxTiltAcc, maxTiltAcc);
      const Ty = clamp(9.81 + ayDes, 2.5, 18.0);

      // Exact rotation from world (Tx, Ty, Tz) to desired (roll, pitch)
      const Bx = cy * Tx - sy * Tz;
      const Bz = sy * Tx + cy * Tz;
      const pitchDes = clamp(Math.atan2(Bx, Ty), -0.52, 0.52);
      const rollDes = clamp(-Math.atan2(Bz, Math.hypot(Bx, Ty)), -0.52, 0.52);

      lastRollDes = rollDes;
      lastPitchDes = pitchDes;

      // Lead + trim compensation for inner attitude loop
      const maxCmdTilt = (obs.gateIndex === 3 && p.y < 0.095 && descendStarted) ? 0.15 : 0.6;
      const rollCmd = clamp(rollDes + rollTrim + 0.35 * (rollDes - att.roll) - 0.04 * rates.roll, -maxCmdTilt, maxCmdTilt);
      const pitchCmd = clamp(pitchDes + pitchTrim + 0.35 * (pitchDes - att.pitch) - 0.04 * rates.pitch, -maxCmdTilt, maxCmdTilt);

      // Thrust magnitude calculation
      let thrustCmd = (Ty / Math.max(0.65, dirY) - dyEst / Math.max(0.65, dirY)) / kT;
      if (obs.gateIndex === 3 && descendStarted && p.y <= 0.085 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) < 0.12) {
        // Gentle hold on the pad
        thrustCmd = Math.min(thrustCmd, 0.25);
      }
      thrustCmd = clamp(thrustCmd, 0, 1);
      lastThrust = thrustCmd;

      const yawRate = clamp(-1.5 * att.yaw - 0.2 * rates.yaw, -0.6, 0.6);
      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate };
    },
  };
}

