export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let stepCount = 0;
  let uLag = 0;
  let kT = 20.5;
  let massEst = 0.775;

  // Observer states
  let vxEst = 0, vyEst = 0, vzEst = 0;
  let dxEst = 0, dyEst = 0, dzEst = 0;

  // Attitude trim integral (lag-compensated)
  let rollTrim = 0, pitchTrim = 0;
  let lastRollDes = 0, lastPitchDes = 0, lastThrust = 0.5;

  // Navigation state
  let targetIndex = -1;
  let phase = 'approach';
  let alignCount = 0;
  let descendStarted = false;
  let prevGateY = 1.05, prevGateZ = -0.85, prevGateX = -2.1;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      const dragCoeff = 0.42 / massEst;
      let axActual = 0, ayActual = 0, azActual = 0;

      if (stepCount === 0) {
        vxEst = v.x; vyEst = v.y; vzEst = v.z;
        prevGateX = p.x; prevGateY = 1.05; prevGateZ = -0.85;
      } else {
        uLag += (lastThrust - uLag) * (1 - Math.exp(-dt / 0.04));
        const airborne = p.y > 0.095;

        if (airborne) {
          const ayModel = kT * uLag * dirY - dragCoeff * vyEst - 9.81;
          const vyPred = vyEst + (ayModel + dyEst) * dt;
          const evy = v.y - vyPred;
          vyEst = vyPred + 0.65 * evy;
          dyEst = clamp(dyEst + 18.0 * evy, -8.0, 8.0);
          ayActual = ayModel + dyEst;

          if (uLag > 0.25 && dirY > 0.7) {
            kT = clamp(kT + 0.8 * dyEst * dt, 13.0, 27.0);
            massEst = clamp(15.0 / kT, 0.6, 0.95);
          }
        } else {
          vyEst = v.y;
          dyEst = 0;
        }

        const uSpec = clamp(kT * uLag + (dirY > 0.5 ? dyEst / dirY : 0), 0, 28.0);
        const axNoWind = uSpec * dirX - dragCoeff * vxEst;
        const azNoWind = uSpec * dirZ - dragCoeff * vzEst;

        if (airborne) {
          const vxPred = vxEst + (axNoWind + dxEst) * dt;
          const evx = v.x - vxPred;
          vxEst = vxPred + 0.65 * evx;
          dxEst = clamp(dxEst + 18.0 * evx, -11.0, 11.0);

          const vzPred = vzEst + (azNoWind + dzEst) * dt;
          const evz = v.z - vzPred;
          vzEst = vzPred + 0.65 * evz;
          dzEst = clamp(dzEst + 18.0 * evz, -11.0, 11.0);

          axActual = axNoWind + dxEst;
          azActual = azNoWind + dzEst;

          // Lag-compensated attitude trim: subtract 0.14 * rate so dynamic motion isn't integrated
          rollTrim = clamp(rollTrim + 0.9 * (lastRollDes - att.roll - 0.14 * rates.roll) * dt, -0.25, 0.25);
          pitchTrim = clamp(pitchTrim + 0.9 * (lastPitchDes - att.pitch - 0.14 * rates.pitch) * dt, -0.25, 0.25);
        } else {
          vxEst = v.x;
          vzEst = v.z;
        }
      }
      stepCount++;

      // Navigation & Waypoint Logic
      let tx, ty, tz;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let kpX = 6.5, kdX = 4.6, kaX = 0.35;
      let kpZ = 8.5, kdZ = 5.5, kaZ = 0.42;
      let kpY = 7.5, kdY = 4.6;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          if (targetIndex >= 0) {
            // Just crossed a gate: record its coordinates
            prevGateX = p.x;
            prevGateY = p.y;
            prevGateZ = p.z;
          }
          targetIndex = obs.gateIndex;
          phase = 'approach';
          alignCount = 0;
        }

        // Smooth transition right after crossing previous gate so we don't clip its frame if pushed back
        if (obs.gateIndex > 0 && p.x < prevGateX + 0.12) {
          const u = clamp((p.x - prevGateX) / 0.12, 0, 1);
          ty = prevGateY + u * (gate.y - prevGateY);
          tz = prevGateZ + u * (gate.z - prevGateZ);
        } else {
          ty = gate.y;
          tz = gate.z;
        }

        const errZ = Math.abs(p.z - gate.z);
        const errY = Math.abs(p.y - gate.y);
        const distToPlane = gate.x - p.x;
        const tCross = clamp(distToPlane / Math.max(vxEst, 0.45), 0.04, 0.35);
        const predZ = Math.abs((p.z + vzEst * tCross) - gate.z);
        const predY = Math.abs((p.y + vyEst * tCross) - gate.y);

        const safeNow = errZ < 0.017 && predZ < 0.019 && Math.abs(vzEst) < 0.09 && errY < 0.075 && predY < 0.085 && Math.abs(vyEst) < 0.25;
        const stillSafe = errZ < 0.023 && predZ < 0.024 && Math.abs(vzEst) < 0.15 && errY < 0.10 && predY < 0.11;

        if (phase === 'approach') {
          tx = gate.x - 0.24;
          if (distToPlane < 0.34 && safeNow) {
            alignCount++;
            if (alignCount >= 3) phase = 'cross';
          } else {
            alignCount = 0;
          }
        }

        if (phase === 'cross') {
          if (distToPlane > 0.015 && !stillSafe) {
            phase = 'approach';
            alignCount = 0;
            tx = gate.x - 0.22;
            kpX = 9.0; kdX = 5.2;
          } else {
            tx = gate.x + 0.35;
            vxRef = 0.75;
          }
        }

        if (distToPlane < 0.55) {
          kpZ = 10.5; kdZ = 6.2; kaZ = 0.48;
          kpY = 9.0; kdY = 5.2;
        }
      } else {
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const horizErr = Math.hypot(p.x - pad.x, p.z - pad.z);
        const horizSpeed = Math.hypot(vxEst, vzEst);

        if (!descendStarted) {
          ty = clamp(0.18 + 0.85 * horizErr, 0.18, 1.05);
          if (horizErr < 0.105 && horizSpeed < 0.24 && p.y < 0.26) {
            descendStarted = true;
          }
        }
        if (descendStarted) {
          if (horizErr > 0.135) {
            ty = 0.12;
          } else {
            ty = 0.045;
          }
          kpX = 8.0; kdX = 5.0; kaX = 0.40;
          kpZ = 8.0; kdZ = 5.0; kaZ = 0.40;
        }
      }

      // Desired accelerations
      const axDes = kpX * (tx - p.x) + kdX * (vxRef - vxEst);
      const azDes = kpZ * (tz - p.z) + kdZ * (vzRef - vzEst);
      const ayDes = kpY * (ty - p.y) + kdY * (vyRef - vyEst);

      const axThrustCmd = axDes - dxEst + dragCoeff * vxEst + kaX * (axDes - axActual);
      const azThrustCmd = azDes - dzEst + dragCoeff * vzEst + kaZ * (azDes - azActual);
      const ayThrustCmd = ayDes + dragCoeff * vyEst;

      const maxTiltAcc = (obs.gateIndex === 3 && p.y < 0.12) ? 1.5 : 7.0;
      const Tx = clamp(axThrustCmd, -maxTiltAcc, maxTiltAcc);
      const Tz = clamp(azThrustCmd, -maxTiltAcc, maxTiltAcc);
      const Ty = clamp(9.81 + ayThrustCmd, 2.5, 18.0);

      const Bx = cy * Tx - sy * Tz;
      const Bz = sy * Tx + cy * Tz;
      const pitchDes = clamp(Math.atan2(Bx, Ty), -0.52, 0.52);
      const rollDes = clamp(-Math.atan2(Bz, Math.hypot(Bx, Ty)), -0.52, 0.52);

      lastRollDes = rollDes;
      lastPitchDes = pitchDes;

      const maxCmdTilt = (obs.gateIndex === 3 && p.y < 0.095 && descendStarted) ? 0.15 : 0.6;
      const rollCmd = clamp(rollDes + rollTrim - 0.10 * rates.roll, -maxCmdTilt, maxCmdTilt);
      const pitchCmd = clamp(pitchDes + pitchTrim - 0.10 * rates.pitch, -maxCmdTilt, maxCmdTilt);

      let thrustCmd = (Ty / Math.max(0.65, dirY) - dyEst / Math.max(0.65, dirY)) / kT;
      if (obs.gateIndex === 3 && descendStarted && p.y <= 0.085 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) < 0.12) {
        thrustCmd = Math.min(thrustCmd, 0.20);
      }
      thrustCmd = clamp(thrustCmd, 0, 1);
      lastThrust = thrustCmd;

      const yawRate = clamp(-1.5 * att.yaw - 0.2 * rates.yaw, -0.6, 0.6);
      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate };
    },
  };
}

