// Test how much z moves during a 0.2s 8m/s gust with lookahead wind compensation!
for (const lead of [0.0, 0.06, 0.09, 0.11]) {
  let z = 0, vz = 0, att = 0, rate = 0, integ = 0, m = 0;
  const lag = 0.05, mass = 0.75, dt = 0.01;
  let maxErr = 0;
  for (let step = 0; step < 300; step++) {
    const t = step * dt;
    // Average wind in [t, t + lead]
    let wLead = 0;
    const N = 5;
    for (let k = 0; k <= N; k++) {
      const tk = t + (k / N) * lead;
      if (tk >= 1.0 && tk < 1.2) wLead += 8.0 / (N + 1);
    }
    const dWindLead = (0.42 / mass) * wLead;
    const azDes = 10.0 * (0 - z) + 6.0 * (0 - vz);
    const azThrustCmd = azDes - dWindLead + (0.42 / mass) * vz;
    const rollDes = Math.max(-0.52, Math.min(0.52, -Math.atan2(azThrustCmd, 9.81)));
    const rollCmd = Math.max(-0.6, Math.min(0.6, rollDes - 0.10 * rate));
    for (let sub = 0; sub < 2; sub++) {
      const dts = 0.005;
      const ts = t + sub * dts;
      const err = rollCmd - att;
      integ = Math.max(-0.35, Math.min(0.35, integ + err * dts));
      const accCmd = 65 * err - 13 * rate + 22 * integ;
      m += (accCmd - m) * (1 - Math.exp(-dts / lag));
      rate += (m - 0.4 * rate) * dts;
      att += rate * dts;
      const windZ = (ts >= 1.0 && ts < 1.2) ? 8.0 : 0;
      const forceZ = mass * 9.81 * (-Math.sin(att)) + 0.42 * (windZ - vz);
      vz += (forceZ / mass) * dts;
      z += vz * dts;
    }
    maxErr = Math.max(maxErr, Math.abs(z));
  }
  console.log({lead, maxErrMeters: +maxErr.toFixed(4)});
}
